  } as const;
  export type IconName = keyof typeof P;
  /** Whether the set draws `name` (a packing category's own emoji, say, is not a name). */
  export const isIcon = (name: string): name is IconName => Object.hasOwn(P, name);

  /** A drawing's shapes (path / circle / rect and their attributes), parsed once a name: no {@html}. */
  type Shape = { tag: 'path' | 'circle' | 'rect'; a: Record<string, string> };
  const parsed = new Map<IconName, Shape[]>();
  function shapes(n: IconName): Shape[] {
    let s = parsed.get(n);
    if (!s) {
      s = [...P[n].matchAll(/<(path|circle|rect)\s([^>]*?)\/>/g)].map((m) => ({
        tag: m[1] as Shape['tag'],
        a: Object.fromEntries([...m[2].matchAll(/([\w-]+)="([^"]*)"/g)].map((x) => [x[1], x[2]]))
      }));
      parsed.set(n, s);
    }
    return s;
  }
</script>

<script lang="ts">
  interface Props {
    /** An IconName; any other string draws the pin. */
    name: IconName | (string & {});
    /** px, square (default 22). */
    size?: number;
    /** Filled in currentColor (the star of a shortlisted campsite). */
    fill?: boolean;
    /** The stroke width (default 1.75; the tick inside a filled circle 2.6). */
    stroke?: number;
  }
  let { name, size = 22, fill = false, stroke = 1.75 }: Props = $props();
  const body = $derived(shapes(isIcon(name) ? name : 'pin'));
</script>

<svg class="q-ic" width={size} height={size} viewBox="0 0 24 24" fill={fill ? 'currentColor' : 'none'} stroke="currentColor"
  stroke-width={stroke} stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
  {#each body as s, i (i)}
    {#if s.tag === 'path'}<path d={s.a.d} />{:else if s.tag === 'circle'}<circle cx={s.a.cx} cy={s.a.cy} r={s.a.r} />{:else}<rect x={s.a.x} y={s.a.y} width={s.a.width} height={s.a.height} rx={s.a.rx} />{/if}
  {/each}
</svg>

<style>
  .q-ic { flex: none; display: block; }
</style>
